style.css:
@-moz-document domain("roblox.com") {
/* Main background */
body {
    background: url("https://imgur.com/a/Sl5tDDi") no-repeat center center fixed !important;
    background-size: cover !important;
}

/* Makes content slightly transparent for style */
.content,
.container-main,
#container-main,
.roblox-home-page,
.game-home-page-container {
    background-color: rgba(255, 255, 255, 0.75) !important;
    border-radius: 15px !important;
}

/* Optional blur effect */
.content {
    backdrop-filter: blur(6px);
}

/* Removes default Roblox backgrounds */
body,
body.light-theme,
body.dark-theme {
    background-color: transparent !important;
}
}
